  132	    private function enqueue(AiProfile $profile, AiWorkItem $sessionWorkItem, AiWorkKind $kind, array $payload, ?CarbonImmutable $dueAt = null, string $keySuffix = ''): void
  133	    {
  134	        AiWorkItem::query()->firstOrCreate(
  135	            ['idempotency_key' => 'intent:session:' . $sessionWorkItem->id . $keySuffix],
  136	            [
  137	                'player_id' => $profile->player_id,
  138	                'kind' => $kind,
  139	                'due_at' => $dueAt ?? $this->clock->now(),
  140	                'schedule_generation' => (int) ($sessionWorkItem->schedule_generation ?? 1),
  141	                'state' => AiWorkState::Pending,
  142	                'payload' => $payload,
  143	            ],
  144	        );
