  229	    /**
  230	     * One intent per queue the planner found free and payable: a building per planet and one
  231	     * technology. Legality is re-asked here rather than trusted from the decision, and the step the
  232	     * planner verified travels with the intent, so the schedule and the executor name one objective.
  233	     * The first step keeps the session's own key, so a retried session converges on the same work.
  234	     */
  235	    private function fillQueues(AiProfile $profile, AiWorkItem $sessionWorkItem, string $keyPrefix): int
  236	    {
  237	        $steps = $this->queueableBuildingPlanner->steps($profile->player_id);
  238	        foreach ($steps as $index => $step) {
  239	            [$kind, $payload] = $step instanceof QueueableResearch
  240	                ? [AiWorkKind::QueueResearch, [self::PAYLOAD_RESEARCH_ID => $step->researchId]]
  241	                : [AiWorkKind::BuildFirstBuilding, [self::PAYLOAD_BUILDING_ID => $step->buildingId]];
  242	
  243	            $this->enqueue($profile, $sessionWorkItem, $kind, [
  244	                self::PAYLOAD_PLANET_ID => $step->planetId,
  245	                ...$payload,
  246	                self::PAYLOAD_REASON => $step->reason,
  247	            ], $this->clock->now()->addSeconds($index * self::SECONDS_BETWEEN_PLANETS), $keyPrefix . ($index === 0 ? '' : ':' . $index));
  248	        }
  249	
  250	        return count($steps);
  251	    }
